return Mono.defer(() -> databaseClient.sql("INSERT INTO audit_trail (actor, action, outcome, occurred_at, correlation_id) VALUES (:actor, :action, :outcome, :occurredAt, :correlationId)")
        .bind("actor", entry.actor())
        .bind("action", entry.action())
        .bind("outcome", entry.outcome())
        .bind("occurredAt", OffsetDateTime.ofInstant(entry.timestamp(), ZoneOffset.UTC))
        .bind("correlationId", entry.correlationId())
        .fetch()
        .rowsUpdated()
        .then())
        .onErrorResume(error -> {
            meterRegistry.counter("telemetry.pipeline.dropped", "stage", "audit").increment();
            return Mono.empty();
        });
